-- ============================================================
-- 39_performance_dashboard.sql
--
-- Backs the new Performance page (weekly/monthly executive
-- dashboard), modeled on the Report Monthly/Weekly workbook.
--
--  * adds the columns the Weekly Entry tab tracks that
--    weekly_metrics was missing
--  * estimate_status_monthly: the Estimate $ Status block
--    (total / pending / accepted / invoiced / lost, $ and count)
--  * social_followers: the Followers row (month, platform, count)
--  * imports 10 weeks of Weekly Entry (Jul 6 - Sep 7 2026) and
--    3 months of Estimate $ Status (Jul - Sep 2026)
--
-- Run any time. Safe to re-run.
-- ============================================================

alter table weekly_metrics add column if not exists jobs_costed int not null default 0;
alter table weekly_metrics add column if not exists still_needs_costing int not null default 0;
alter table weekly_metrics add column if not exists appointments_set int not null default 0;
alter table weekly_metrics add column if not exists calls_answered int not null default 0;
alter table weekly_metrics add column if not exists missed_calls_returned int not null default 0;
alter table weekly_metrics add column if not exists estimates_accepted int not null default 0;
alter table weekly_metrics add column if not exists estimates_invoiced int not null default 0;
alter table weekly_metrics add column if not exists videos_to_edit int not null default 0;
alter table weekly_metrics add column if not exists videos_ready int not null default 0;
alter table weekly_metrics add column if not exists first_time_calls_answered int not null default 0;
alter table weekly_metrics add column if not exists first_time_calls_missed int not null default 0;

create table if not exists estimate_status_monthly (
  month         date primary key,
  total_amt     numeric(14,2) not null default 0,
  total_ct      int not null default 0,
  pending_amt   numeric(14,2) not null default 0,
  pending_ct    int not null default 0,
  accepted_amt  numeric(14,2) not null default 0,
  accepted_ct   int not null default 0,
  invoiced_amt  numeric(14,2) not null default 0,
  invoiced_ct   int not null default 0,
  lost_amt      numeric(14,2) not null default 0,
  lost_ct       int not null default 0,
  updated_at    timestamptz not null default now()
);
alter table estimate_status_monthly enable row level security;
drop policy if exists team_all on estimate_status_monthly;
create policy team_all on estimate_status_monthly for all to authenticated using (true) with check (true);

create table if not exists social_followers (
  follower_id  uuid primary key default gen_random_uuid(),
  month        date not null,
  platform     text not null,
  followers    int not null default 0,
  unique (month, platform)
);
alter table social_followers enable row level security;
drop policy if exists team_all on social_followers;
create policy team_all on social_followers for all to authenticated using (true) with check (true);

