-- verify
select
  (select count(*) from weekly_metrics where week_ending >= '2026-07-01') as weeks_imported,
  (select round(sum(calls_received)) from weekly_metrics) as total_calls_received,
  (select count(*) from estimate_status_monthly) as est_status_months,
  (select round(sum(accepted_amt)) from estimate_status_monthly) as total_accepted_dollars;
